summary={'cleanup':json.loads((OUT/'cleanup.json').read_text()),'qt_libraries':json.loads((OUT/'qt-libraries.json').read_text()),'toolchains':json.loads((OUT/'toolchains.json').read_text()),'graphics_host':json.loads((OUT/'graphics-host.json').read_text()),'results':results,'builds':builds,'observations':observations,'reference':reference,'source_sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'code_lines':loc,'physical_lines':len(source_lines),'protocol':'Native startup/capture observation first, then three interleaved rounds in matrix order. The Skia/OpenGL measurements were discarded after detecting fallback, then replaced by three separate runs with the explicit OpenGL feature. 4s warmup, 20s idle, 500ms sampling, X11/XWayland, scale1, 1000x680, one owned process group at a time, no compilation or strace during sampling. No app polling. All modes use identical UI/Docker source and pinned Cargo.lock.','limits':'Linux only, idle only, GPU/compositor memory not fully represented by process RSS/PSS. WGPU_BACKEND=vulkan and WGPU_ADAPTER_NAME=Intel requested; external GLX summary reports Intel Arc. Actual per-process adapter selection is not independently instrumented. Renderer dependency build timings are cache/download dependent, not controlled clean-build comparisons. Skia software/WGPU share a family binary; Skia/OpenGL uses an explicit OpenGL-feature binary. Qt uses system shared libraries.'}
rows='';screens='';details='';libraries=''
for key,item in results.items():
 config=item['config'];runs=item['runs'];ob=observations.get(key,{})
 if len(runs)==3:
  item['medians']={f:statistics.median(r[f] for r in runs) for f in ['idle_rss_median_bytes','idle_pss_median_bytes','idle_cpu_percent_one_core','visible_after_seconds','initial_load_ms']}
  item['all_ids_match']=all(r['matches_reference'] for r in runs)
  med=item['medians'];size=item['build']['binary_bytes']/1048576
  cells=f'<td>{size:.2f} MiB</td><td>{med["idle_rss_median_bytes"]/1048576:.2f} MiB</td><td>{med["idle_pss_median_bytes"]/1048576:.2f} MiB</td><td>{med["idle_cpu_percent_one_core"]:.2f}%</td><td>{med["visible_after_seconds"]:.3f}s</td><td>{item["all_ids_match"]}</td>'
 else:cells=f'<td colspan="6">{html.escape(item["status"])} — {len(runs)} completed runs</td>'
 rows+=f'<tr><th>{config["label"]}<br><small>{config["kind"]}</small></th>{cells}</tr>'
 image=OUT/f'{key}-1.png'
 if not image.exists():image=OUT/f'{key}-native.png'
 if image.exists():
  url='data:image/png;base64,'+base64.b64encode(image.read_bytes()).decode()
  screens+=f'<figure><figcaption>{config["label"]} · {html.escape(item["status"])}</figcaption><a href="{url}" target="_blank"><img src="{url}" alt="{config["label"]} native capture"></a></figure>'
 if item.get('error'):details+=f'<details><summary>{config["label"]}: {html.escape(item["status"])}</summary><pre style="white-space:pre-wrap">{html.escape(item["error"])}</pre></details>'
 if runs:
  libs=', '.join(Path(p).name for p in runs[0]['graphics_libraries']) or 'None recorded'
  libraries+=f'<tr><th>{config["label"]}</th><td style="overflow-wrap:anywhere">{html.escape(libs)}</td><td>{len(runs[0]["shared_libraries"])}</td></tr>'
for key,item in results.items():
 for r in item['runs']:
  details+=f'<p class="muted">{item["config"]["label"]} · run {r["run"]}: RSS {r["idle_rss_median_bytes"]/1048576:.2f} MiB; PSS {r["idle_pss_median_bytes"]/1048576:.2f} MiB; CPU {r["idle_cpu_percent_one_core"]:.3f}%; IDs match: {r["matches_reference"]}.</p>'
charts=''
for title,field in [('Idle RSS (MiB)','idle_rss_median_bytes'),('ELF executable (MiB)','binary_bytes')]:
 measured=[i for i in results.values() if len(i['runs'])==3]
 values=[(i['build'][field] if field=='binary_bytes' else i['medians'][field])/1048576 for i in measured]
 maximum=max(values,default=1) or 1
 bars=''.join(f'<div class="bar-row"><span>{i["config"]["label"]}</span><div class="track"><i style="width:{v/maximum*100:.3f}%;background:var(--accent,#85e2bf)"></i></div><strong>{v:.2f}</strong></div>' for i,v in zip(measured,values))
 charts+=f'<article class="metric"><h3>{title}</h3>{bars}</article>'
build_rows=''.join(f'<tr><th>{name}</th><td>{b["exit_code"]}</td><td>{b["elapsed_s"]:.2f}s</td><td>{("%.2f MiB" % (b["binary_bytes"]/1048576)) if "binary_bytes" in b else "Unavailable"}</td><td>{html.escape(b["cache"])}</td></tr>' for name,b in builds.items())
raw='data:application/json;base64,'+base64.b64encode(json.dumps(summary,indent=2).encode()).decode()
qt_extra=f' The Qt run mapped libQt6 files totaling {summary["qt_libraries"]["total_file_bytes"]/1048576:.2f} MiB on disk, outside its executable; plugins and other dependencies are additional. This is not a complete bundle-size total.'
stamp=datetime.now(ZoneInfo('America/Toronto')).strftime('%Y-%m-%d %H:%M %Z')
